using UnityEngine;

namespace HimoHito
{
    // Display-only knit sleeves. Geometry samples the unchanged doll torso artwork;
    // no LineRenderer, physics body, collider, input writer or new pose clock.
    public sealed class IntegratedWoolArms : MonoBehaviour
    {
        const int Rings=22,Columns=10;
        sealed class Sleeve
        {
            public Mesh mesh;public MeshRenderer renderer;public Transform transform;
            public Vector3[] vertices=new Vector3[(Rings+1)*(Columns+1)];
            public Color[] colors=new Color[(Rings+1)*(Columns+1)];
            public Vector2[] uv=new Vector2[(Rings+1)*(Columns+1)];
        }
        Sleeve left,right;Material material;
        MaterialPropertyBlock properties;
        public Vector3 LeftHand{get;private set;}public Vector3 RightHand{get;private set;}
        public float MaximumBoneLengthError{get;private set;}
        public int VisibleSleeves=>(left.renderer.enabled?1:0)+(right.renderer.enabled?1:0);
        void Awake()
        {
            properties=new MaterialPropertyBlock();
            material=new Material(Resources.Load<Shader>("PlayerPresentationYarn"));
            material.name="Original torso-knit sleeves - no rope texture";
            material.mainTexture=Resources.Load<Texture2D>("Art/HimoHitoCraftPlayer-v1");
            material.SetColor("_RendererColor",Color.white);material.SetVector("_Flip",Vector4.one);
            left=Create("Far knit arm");right=Create("Near knit arm");
        }
        Sleeve Create(string name)
        {
            var child=new GameObject(name);child.transform.SetParent(transform,false);
            var sleeve=new Sleeve{transform=child.transform,mesh=new Mesh{name=name}};
            child.AddComponent<MeshFilter>().sharedMesh=sleeve.mesh;
            sleeve.renderer=child.AddComponent<MeshRenderer>();sleeve.renderer.sharedMaterial=material;
            sleeve.renderer.enabled=false;
            int[] triangles=new int[Rings*Columns*6];int i=0;
            for(int y=0;y<Rings;y++)for(int x=0;x<Columns;x++)
            {
                int v=y*(Columns+1)+x;
                triangles[i++]=v;triangles[i++]=v+Columns+1;triangles[i++]=v+1;
                triangles[i++]=v+1;triangles[i++]=v+Columns+1;triangles[i++]=v+Columns+2;
            }
            sleeve.mesh.vertices=sleeve.vertices;sleeve.mesh.triangles=triangles;
            return sleeve;
        }
        public void Draw(SpriteRenderer source,Vector4 landmarks,Vector4 angles,float rotation,float weight)
        {
            if(!source.enabled||weight<=.001f){Hide();return;}
            Vector4 a=source.flipX?new Vector4(-angles.z,-angles.w,-angles.x,-angles.y):angles;
            Vector2 neck=new Vector2(landmarks.x,landmarks.y);float width=landmarks.z;
            LeftHand=DrawSleeve(left,source,neck,width,-1,a.x,a.y,rotation,weight,.91f);
            RightHand=DrawSleeve(right,source,neck,width,1,a.z,a.w,rotation,weight,1f);
        }
        Vector3 DrawSleeve(Sleeve sleeve,SpriteRenderer source,Vector2 neck,float width,
            float side,float upperAngle,float lowerAngle,float rotation,float weight,float shade)
        {
            // Root lives inside the upper torso, not at its loose yarn tails.
            Vector2 shoulder=neck+new Vector2(side*width*.205f,-width*.155f);
            float upper=width*.28f,lower=width*.26f;
            Vector2 elbow=shoulder+Down(upperAngle)*upper;
            Vector2 hand=elbow+Down(lowerAngle)*lower;
            MaximumBoneLengthError=Mathf.Max(MaximumBoneLengthError,
                Mathf.Abs(Vector2.Distance(shoulder,elbow)/width-.28f),
                Mathf.Abs(Vector2.Distance(elbow,hand)/width-.26f));
            for(int r=0;r<=Rings;r++)
            {
                float t=r/(float)Rings;
                // Rounded join follows fixed shoulder/elbow/hand bones, never stretches.
                Vector2 center,along;
                if(t<.38f){center=Vector2.Lerp(shoulder,elbow,t/.5f);along=(elbow-shoulder).normalized;}
                else if(t>.62f){center=Vector2.Lerp(elbow,hand,(t-.5f)/.5f);along=(hand-elbow).normalized;}
                else
                {
                    Vector2 p=Vector2.Lerp(shoulder,elbow,.76f),q=Vector2.Lerp(elbow,hand,.24f);
                    float s=(t-.38f)/.24f;
                    center=(1-s)*(1-s)*p+2*(1-s)*s*elbow+s*s*q;
                    along=(2*(1-s)*(elbow-p)+2*s*(q-elbow)).normalized;
                }
                Vector2 normal=new Vector2(-along.y,along.x);
                float cap=t>.88f?Mathf.Sqrt(Mathf.Max(0,1-Mathf.Pow((t-.88f)/.12f,2))):1;
                float radius=width*Mathf.Lerp(.120f,.090f,t)*cap;
                for(int c=0;c<=Columns;c++)
                {
                    float u=c/(float)Columns,across=u*2-1;int index=r*(Columns+1)+c;
                    Vector2 point=center+normal*radius*across;
                    sleeve.vertices[index]=sleeve.transform.InverseTransformPoint(World(point));
                    // Torso centre: no eyes, background, original arms or feet in this UV strip.
                    // Pixel density follows the original knitted body rather than a tiled rope.
                    sleeve.uv[index]=new Vector2(Mathf.Lerp(464,556,u)/1024f,1-Mathf.Lerp(938,1196,t)/1536f);
                    float roundShade=Mathf.Lerp(.64f,1.02f,Mathf.Pow(Mathf.Max(0,1-across*across),.42f));
                    float alpha=Mathf.Clamp01((1-Mathf.Abs(across))*7)*weight;
                    sleeve.colors[index]=new Color(roundShade*shade,roundShade*shade,roundShade*shade,alpha);
                }
            }
            sleeve.mesh.vertices=sleeve.vertices;sleeve.mesh.uv=sleeve.uv;sleeve.mesh.colors=sleeve.colors;sleeve.mesh.RecalculateBounds();
            sleeve.renderer.enabled=true;sleeve.renderer.sortingLayerID=source.sortingLayerID;
            sleeve.renderer.sortingOrder=source.sortingOrder+(side<0?-1:1);
            Bounds bounds=source.sprite.bounds;
            properties.Clear();properties.SetVector("_SpriteBounds",new Vector4(bounds.min.x,bounds.min.y,bounds.size.x,bounds.size.y));
            properties.SetVector("_Motion",Vector4.zero);properties.SetVector("_SwingPose",Vector4.zero);
            properties.SetVector("_ArmRemoval",Vector4.zero);sleeve.renderer.SetPropertyBlock(properties);
            return World(hand);
            Vector3 World(Vector2 point)
            {
                Vector2 d=point-neck;float s=Mathf.Sin(rotation),c=Mathf.Cos(rotation);
                point=neck+new Vector2(c*d.x-s*d.y,s*d.x+c*d.y);
                if(source.flipX)point.x=-point.x;
                return source.transform.TransformPoint(point);
            }
        }
        static Vector2 Down(float degrees){float a=degrees*Mathf.Deg2Rad;return new Vector2(Mathf.Sin(a),-Mathf.Cos(a));}
        public void Hide(){if(left!=null)left.renderer.enabled=false;if(right!=null)right.renderer.enabled=false;}
        void OnDisable()=>Hide();
        void OnDestroy(){if(material)Destroy(material);if(left?.mesh)Destroy(left.mesh);if(right?.mesh)Destroy(right.mesh);}
    }
}
